import{_ as l,a0 as d,w as o,s as g,ao as p,I as n,x as s,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step","title":"如何在 RHEL 9 上分步安装 PgAdmin4","tag":"202303","desc":""},"relativePath":"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step.md","filePath":"[post].md"}'),r={name:"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step.md"};function h(m,i,c,u,b,k){const t=d("Link");return o(),g("div",null,[i[18]||(i[18]=p('<h1 id="如何在-rhel-9-上分步安装-pgadmin4" tabindex="-1">如何在 RHEL 9 上分步安装 PgAdmin4 <a class="header-anchor" href="#如何在-rhel-9-上分步安装-pgadmin4" aria-label="Permalink to “如何在 RHEL 9 上分步安装 PgAdmin4”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/12/080937o03a11xsz99zawzm.jpg" alt=""></p><p>PgAdmin4 是一个自由开源的基于网络的 PostgreSQL 管理和开发平台。它可以与本地或远程的服务器上的 PostgreSQL 数据库服务器进行交互，并使用直观的交互式仪表板显示服务器的统计数据。</p><p>PgAdmin4 是对 PgAdmin3 的重写，提供了以下显著的功能：</p><ul><li>具有直观的实时监控仪表盘的响应式 Web UI。</li><li>改进的 Web 界面，具有很酷的新面板和图标。</li><li>带有语法高亮的 SQL 查询编辑器。</li><li>全面的文档。</li><li>帮助你入门的有用提示。</li></ul><p>在本指南中，我们将演示如何在 RHEL 9 上安装 PgAdmin4。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3>',7)),n("p",null,[i[1]||(i[1]=s("在开始之前，确保你有一台 RHEL 9 服务器实例并安装了 PostgreSQL 数据库。请查看如何在 RHEL 9 上 ",-1)),e(t,{href:"https://www.linuxtechi.com/how-to-install-postgresql-on-rhel/"},{default:a(()=>[...i[0]||(i[0]=[s("安装 PostgreSQL 15",-1)])]),_:1}),i[2]||(i[2]=s(" 的指南。",-1))]),i[19]||(i[19]=p('<p>在安装了 PostgreSQL 服务器后，继续执行以下步骤。</p><h3 id="步骤-1-在-rhel-9-上添加-pgadmin4-仓库" tabindex="-1">步骤 1）在 RHEL 9 上添加 PgAdmin4 仓库 <a class="header-anchor" href="#步骤-1-在-rhel-9-上添加-pgadmin4-仓库" aria-label="Permalink to “步骤 1）在 RHEL 9 上添加 PgAdmin4 仓库”">​</a></h3><p>第一步是在 RHEL 9 上添加 PgAdmin4 仓库。但首先要安装 EPEL 仓库，它提供了基本的软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm</span></span></code></pre></div><p>接下来，安装 PgAdmin4 仓库，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y https://ftp.postgresql.org/pub/pgadmin/pgadmin4/yum/pgadmin4-redhat-repo-2-1.noarch.rpm</span></span></code></pre></div><p>完成后，为 PgAdmin4 和 EPEL 仓库建立一个缓存，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf makecache</span></span></code></pre></div><h3 id="步骤-2-在-rhel-9-上安装-pgadmin4" tabindex="-1">步骤 2）在 RHEL 9 上安装 PgAdmin4 <a class="header-anchor" href="#步骤-2-在-rhel-9-上安装-pgadmin4" aria-label="Permalink to “步骤 2）在 RHEL 9 上安装 PgAdmin4”">​</a></h3><p>安装好 PgAdmin4 和 EPEL 仓库后，继续使用 DNF 包管理器安装 PgAdmin4，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install pgadmin4 -y</span></span></code></pre></div><p>这将安装许多软件包，包括 PgAdmin4、Apache HTTP web 服务器和 Python 软件包，仅举几例：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Install-pgadmin4-rhel9-dnf-command.png" alt=""></p><p>要确认 PgAdmin4 是否已经安装，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm -qi pgadmin4</span></span></code></pre></div><p>这将打印出相当多的信息，包括已安装软件包的名称、版本、发行和架构。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pgadmin4-RPM-Package-Information-RHEL9.png" alt=""></p><h3 id="步骤-3-在-rhel-9-上启动-启用-pgadmin4" tabindex="-1">步骤 3）在 RHEL 9 上启动/启用 PgAdmin4 <a class="header-anchor" href="#步骤-3-在-rhel-9-上启动-启用-pgadmin4" aria-label="Permalink to “步骤 3）在 RHEL 9 上启动/启用 PgAdmin4”">​</a></h3><p>此时，PgAdmin4 已成功安装。然而，你需要更进一步，让它运行起来。要启动 PgAdmin4 服务，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start httpd</span></span></code></pre></div><p>还要确保每次系统启动时都能启动该服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable httpd</span></span></code></pre></div><p>要确认 PgAdmin4 正在运行，请执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status httpd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Start-Enable-Http-Pgadmin-RHEL9.png" alt=""></p><h3 id="步骤-4-在-rhel-9-上初始化-pgadmin4" tabindex="-1">步骤 4）在 RHEL 9 上初始化 PgAdmin4 <a class="header-anchor" href="#步骤-4-在-rhel-9-上初始化-pgadmin4" aria-label="Permalink to “步骤 4）在 RHEL 9 上初始化 PgAdmin4”">​</a></h3><p>PgAdmin4 软件包提供了一个可配置的脚本来设置 PgAdmin 网络服务。这允许你创建一个用户账户，用来验证和配置 SELinux 策略和 Apache Web 服务器。</p><p>因此，如下运行该脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/pgadmin4/bin/setup-web.sh</span></span></code></pre></div><p>提供你将在登录页面上作为登录凭证使用的电子邮件和密码。</p><p>注意:有时，你可能会遇到如下 “semanage: command not found” 的错误。这表明缺少 <code>semanage</code> 包。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/semange-not-found-pgadmin4-rhel9.png" alt=""></p><p>Semanage 是 SELinux（安全增强型 Linux）策略管理工具的简称，是一个用于配置 SELinux 策略某些方面的工具，不需要对策略源进行修改或重新编译。</p><p>为了解决这个错误，你需要检查提供 <code>semanage</code> 的软件包。你可以通过运行以下命令来完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf provides /usr/sbin/semanage</span></span></code></pre></div><p>从输出中，你可以看到 <code>semanage</code> 是由 <code>policycoreutils-python-utils-3.3-6.el9_0.noarch</code> 包提供的。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/DNF-Whatprovides-semanage-RHEL9.png" alt=""></p><p>要安装这个软件包，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install policycoreutils-python-utils -y</span></span></code></pre></div><p>再一次如下运行 Pgadmin4 安装脚本。 提供电子邮件地址和密码，在提示时输入 <code>y</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/pgadmin4/bin/setup-web.sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/pgadmin-setup-web-script-rhel9.png" alt=""></p><h3 id="步骤-5-访问-pgadmin4-的-web-界面" tabindex="-1">步骤 5）访问 PgAdmin4 的 Web 界面 <a class="header-anchor" href="#步骤-5-访问-pgadmin4-的-web-界面" aria-label="Permalink to “步骤 5）访问 PgAdmin4 的 Web 界面”">​</a></h3><p>此时，PgAdmin4 已经成功安装。要从网络浏览器访问它，请前往以下地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://server-ip/pgadmin4</span></span></code></pre></div><p>你会看到登录网页界面。请确保提供你在运行安装脚本时提供的 Email 和密码，并点击 “<ruby>登录<rt>Login</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pgadmin4-Login-Page-RHEL9.png" alt=""></p><p>登录后，PgAdmin4 的仪表板将出现在视图中，如图所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Dashboard-Pgadmin4-RHEL9.png" alt=""></p><p>要添加一个可以由 PgAdmin4 管理的服务器，请点击 “<ruby>添加新服务器<rt>Add New Server</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Add-New-PostgreSQL-to-Pgadmin4-RHEL9.png" alt=""></p><p>在 “<ruby>通用<rt>General</rt></ruby>” 选项卡中，填写服务器的名称，并添加注释，以便更好地描述：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/General-Description-Pgadmin-New-PostgreSQL.png" alt=""></p><p>接下来，点击 “<ruby>连接<rt>Connection</rt></ruby>”，填写主机名/地址、端口、维护数据库、用户名和密码。然后最后点击 “<ruby>保存<rt>Save</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Connection-Details-PostgreSQL-Pgadmin4-GUI.png" alt=""></p><p>此后，你会看到 PosrgreSQL 服务器的统计数据显示在互动和直观的仪表板上。在左边的侧边栏，你可以浏览各种 PostgreSQL 参数：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/PostgreSQL-Statistics-Dashboard-Pgadmin4.png" alt=""></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我们希望你觉得本指南内容丰富，请在下面的评论部分发表你的疑问和反馈。</p><hr>',60)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),e(t,{href:"https://www.linuxtechi.com/how-to-install-pgadmin-on-rhel/"},{default:a(()=>[...i[3]||(i[3]=[s("https://www.linuxtechi.com/how-to-install-pgadmin-on-rhel/",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=s("作者：",-1)),e(t,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...i[5]||(i[5]=[s("Pradeep Kumar",-1)])]),_:1}),i[10]||(i[10]=s(" 选题：",-1)),e(t,{href:"https://github.com/lkxed/"},{default:a(()=>[...i[6]||(i[6]=[s("lkxed",-1)])]),_:1}),i[11]||(i[11]=s(" 译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:a(()=>[...i[7]||(i[7]=[s("geekpi",-1)])]),_:1}),i[12]||(i[12]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[8]||(i[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...i[14]||(i[14]=[s("Linux中国",-1)])]),_:1}),i[17]||(i[17]=s(" 荣誉推出",-1))])])}const y=l(r,[["render",h]]);export{w as __pageData,y as default};
